#!/usr/bin/env bash
#
# uninstall.sh — remove the jira-cli-manager launchers.
#
# Removes ~/.local/bin/jira, ~/.local/bin/jira-cli and ~/.local/bin/jira-mcp and nothing else,
# and only when they were written by install.sh (they carry its "Generated by"
# line). A launcher of the same name that belongs to another program is left
# alone and the script stops; pass --force to remove it anyway.
# Your credential (~/.config/jira-cli/.env) and your local configuration
# (teams.yaml, filters.yaml) are NEVER touched: reinstalling must not cost you
# a token, and an uninstall script must not be able to delete one.
#
# The repository virtualenv is left in place too; delete it yourself if you
# want the disk space back. Both extra steps are printed below.
#
#   ./uninstall.sh
#   ./uninstall.sh --force
#   ./uninstall.sh --help
#
set -euo pipefail

REPO_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
VENV_DIR="$REPO_DIR/.venv"
CONFIG_DIR="${JIRA_CONFIG_DIR:-${HOME:-}/.config/jira-cli}"
LAUNCHERS=("jira" "jira-cli" "jira-mcp")
# Must match the second line install.sh writes into every launcher.
LAUNCHER_MARKER="# Generated by jira-cli-manager install.sh. Safe to delete."
FORCE=0

say()  { printf '%s\n' "$*"; }
warn() { printf 'warning: %s\n' "$*" >&2; }
die()  { printf 'error: %s\n' "$*" >&2; exit 1; }

usage() {
    awk 'NR >= 3 && /^#/ { sub(/^# ?/, ""); print; next } NR >= 3 { exit }' "${BASH_SOURCE[0]}"
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --force)   FORCE=1 ;;
        -h|--help) usage; exit 0 ;;
        *)         die "unknown option: $1 (try --help)" ;;
    esac
    shift
done

# --- path safety (same rules as install.sh) ----------------------------------
case "${HOME:-}" in
    /?*) ;;
    *) die "HOME must be set to an absolute path other than / (got '${HOME:-}')" ;;
esac
BIN_DIR="$HOME/.local/bin"

normalize_path() {
    local p
    p="$(printf '%s' "$1" | tr -s '/')"
    while [ "${#p}" -gt 1 ] && [ "${p%/}" != "$p" ]; do
        p="${p%/}"
    done
    printf '%s' "$p"
}

resolve_path() {
    local r
    if r="$(realpath -m -- "$1" 2>/dev/null)" && [ -n "$r" ]; then
        printf '%s' "$r"
    else
        printf '%s' "$1"
    fi
}

is_forbidden_dir() {
    local p="$1" home
    home="$(normalize_path "$HOME")"
    [ "$p" = "/" ] && return 0
    [ "$p" = "$home" ] && return 0
    [ "$p" = "$(resolve_path "$home")" ] && return 0
    case "$home/" in "$p"/*) return 0 ;; esac
    case "$p" in
        /bin|/boot|/dev|/etc|/home|/lib|/lib32|/lib64|/libx32|/media|/mnt|/opt|/proc|/root|/run|/sbin|/snap|/srv|/sys|/tmp|/usr|/var|/var/tmp)
            return 0 ;;
        /Applications|/Library|/System|/Users|/Volumes|/private|/private/tmp|/private/var)
            return 0 ;;
        /bin/*|/boot/*|/dev/*|/etc/*|/lib/*|/lib32/*|/lib64/*|/libx32/*|/proc/*|/run/*|/sbin/*|/sys/*|/usr/*|/System/*)
            return 0 ;;
    esac
    return 1
}

looks_like_config_dir() {
    local dir="$1" f
    for f in .env teams.yaml filters.yaml plans; do
        [ -e "$dir/$f" ] && return 0
    done
    return 1
}

# The config dir is only ever named in advice below, but that advice is an
# `rm -rf`, so a mistaken JIRA_CONFIG_DIR is refused rather than printed.
case "$CONFIG_DIR" in
    *$'\n'*) die "JIRA_CONFIG_DIR must not contain a newline" ;;
    /*) ;;
    *) die "JIRA_CONFIG_DIR must be an absolute path (got '$CONFIG_DIR')" ;;
esac
case "/$CONFIG_DIR/" in
    */../*|*/./*) die "JIRA_CONFIG_DIR must not contain '.' or '..' components (got '$CONFIG_DIR')" ;;
esac
CONFIG_DIR="$(normalize_path "$CONFIG_DIR")"
if is_forbidden_dir "$CONFIG_DIR" || is_forbidden_dir "$(resolve_path "$CONFIG_DIR")"; then
    die "refusing JIRA_CONFIG_DIR='$CONFIG_DIR': it is /, your home directory (or above it), or a system directory. Unset it or point it at the directory install.sh used."
fi
ENV_FILE="$CONFIG_DIR/.env"

# --- launcher ownership ----------------------------------------------------
# Prints "absent", "ours" or "foreign"; a symlink is always foreign.
launcher_state() {
    local path="$1"
    if [ -L "$path" ]; then
        printf 'foreign'
    elif [ ! -e "$path" ]; then
        printf 'absent'
    elif [ -f "$path" ] \
        && [ "$(head -c 4096 "$path" 2>/dev/null | tr -d '\000' | sed -n '2p')" = "$LAUNCHER_MARKER" ]; then
        printf 'ours'
    else
        printf 'foreign'
    fi
}

# Decide for every launcher before removing any, so a refusal leaves all
# three exactly as they were.
foreign=()
for name in "${LAUNCHERS[@]}"; do
    path="$BIN_DIR/$name"
    if [ "$(launcher_state "$path")" = "foreign" ]; then
        foreign+=("$path")
    fi
done
if [ "${#foreign[@]}" -gt 0 ]; then
    if [ "$FORCE" -eq 1 ]; then
        warn "--force: removing files not written by install.sh: ${foreign[*]}"
    else
        for path in "${foreign[@]}"; do
            warn "$path was not written by jira-cli-manager (no '$LAUNCHER_MARKER' line)"
        done
        die "refusing to remove ${foreign[*]}; it belongs to another program. Nothing was removed. Re-run with --force to remove it anyway."
    fi
fi

removed=0
for name in "${LAUNCHERS[@]}"; do
    path="$BIN_DIR/$name"
    state="$(launcher_state "$path")"
    if [ "$state" = "ours" ] || { [ "$state" = "foreign" ] && [ "$FORCE" -eq 1 ]; }; then
        rm -f -- "$path"
        say "removed $path"
        removed=1
    fi
done

[ "$removed" -eq 1 ] || say "no launchers found in $BIN_DIR — nothing to do"

say ""
say "Kept, on purpose:"
say "  $ENV_FILE         (your credential)"
say "  $CONFIG_DIR/      (teams.yaml, filters.yaml)"
say "  $VENV_DIR         (the repository virtualenv)"
say ""
say "To remove those too, do it deliberately:"
say "  rm -rf -- $(printf '%q' "$VENV_DIR")"
if looks_like_config_dir "$CONFIG_DIR"; then
    say "  rm -rf -- $(printf '%q' "$CONFIG_DIR")      # deletes your token: revoke it in Jira first"
else
    say "  ($CONFIG_DIR holds no jira-cli files, so no command is suggested for it)"
fi
say ""
say "Revoking a PAT: avatar -> Profile -> Personal Access Tokens -> Revoke."
